// ── Hardcoded Scenarios carefully engineered for perfect status distribution ──
const scenarios = [
  // 1. KNOWN (auto-solved: yield >85% similarity score)
  { cat: 'known', base: 'Login service timeout', ctx: 'Users are unable to login, requests timeout after 30 seconds' },
  { cat: 'known', base: 'Payment gateway 500 error', ctx: 'Payment processing returns 500 Internal Server Error' },
  { cat: 'known', base: 'Email notifications not sending', ctx: 'System emails (password reset, alerts) not being delivered' },
  { cat: 'known', base: 'API rate limit 429 errors', ctx: 'Third-party API calls returning 429 Too Many Requests' },
  { cat: 'known', base: 'Memory leak in worker service', ctx: 'Worker pod memory usage grows unbounded, OOMKilled after 6h' },

  // 2. MID (assigned to dev with tips: yield 55% - 85% similarity score)
  { cat: 'database', base: 'Database deadlock during concurrent batch checkout', ctx: 'Postgres row-level locks and transaction rollbacks during bulk order processing' },
  { cat: 'frontend', base: 'Auth token refresh race-condition causing random 401 logouts', ctx: 'Concurrent API requests during token expiry cause double refresh, invalidating sessions' },
  { cat: 'devops', base: 'Kubernetes Pod OOMKilled crash loop on image-processor', ctx: 'Memory leak in sharp image resize module during parallel uploads under 300 concurrent requests' },
  { cat: 'ui', base: 'React re-render infinite loop in Safari 17 checkout cart', ctx: 'Infinite hooks dispatch loop from missing dependency array in useMemo causing browser freeze' },
  // 3. UNKNOWN (escalated to Jira: yield <55% similarity score)
  { cat: 'unknown', base: 'Breakroom coffee machine water leak disaster', ctx: 'The primary office coffee maker is leaking gallons of hot water all over the breakroom kitchen floor' },
  { cat: 'unknown', base: 'Conference room furniture broken and damaged', ctx: 'Multiple mesh chairs are broken and the conference room whiteboard has permanent stains' },
  { cat: 'unknown', base: 'Lost physical RFID parking garage keycard', ctx: 'An employee lost their plastic parking garage pass and needs a replacement card issued by building management' }
];

const team = [
  'Sanjay Dutt (DB Architect) <sanjay.d@fixflow.co>',
  'Rajesh Kumar (API Engineer) <rajesh.k@fixflow.co>',
  'Chloe Dupont (DevOps Lead) <chloe.d@fixflow.co>',
  'Elena Rostova (UI/UX Dev) <elena.r@fixflow.co>',
  'Marcus Vance (Frontend Eng) <marcus.v@fixflow.co>',
  'Alex Mercer (Product Manager) <alex.mercer@fixflow.co>',
  'Sarah Jenkins (QA Tester) <sarah.j@fixflow.co>',
  'Daniel Park (SDET) <daniel.p@fixflow.co>'
];

// 2 clients
const clients = [
  { name: 'Jane Miller', email: 'client.jane@retailcorp.com', role: 'Store Manager' },
  { name: 'Robert Chen', email: 'client.robert@retailcorp.com', role: 'Regional Operations Director' }
];

const output = [];

// To ensure a perfect distribution, we explicitly generate:
// - 2 Known tickets (auto-solved)
// - 1 Mid ticket (assigned with KB tips)
// - 2 Unknown tickets (critical facilities/unrelated to code)
const selections = [
  // 2 Known
  scenarios.filter(s => s.cat === 'known')[Math.floor(Math.random() * 5)],
  scenarios.filter(s => s.cat === 'known')[Math.floor(Math.random() * 5)],
  // 1 Mid
  scenarios.filter(s => ['database', 'frontend', 'devops', 'ui'].includes(s.cat))[Math.floor(Math.random() * 4)],
  // 2 Unknown
  scenarios.filter(s => s.cat === 'unknown')[Math.floor(Math.random() * 3)],
  scenarios.filter(s => s.cat === 'unknown')[Math.floor(Math.random() * 3)]
];

// Shuffle selections to simulate organic ticket submission order
const shuffledSelections = selections.sort(() => Math.random() - 0.5);

for (let i = 0; i < 5; i++) {
  const s = shuffledSelections[i];
  const shuffledTeam = [...team].sort(() => Math.random() - 0.5);
  const participants = shuffledTeam.slice(0, 3).join(', ');

  const randId = Math.random().toString(36).substring(2, 8).toUpperCase();
  const timestamp = Date.now().toString().slice(-6);
  const orderNum = 'ORD-' + Math.floor(100000 + Math.random() * 900000);
  const uuidSample = 'usr_' + Math.floor(10000 + Math.random() * 90000);
  const port = Math.floor(3000 + Math.random() * 6000);

  // Pick reporter
  let reporter = '';
  if (s.cat === 'unknown' || Math.random() > 0.5) {
    const cl = clients[Math.floor(Math.random() * clients.length)];
    reporter = cl.name + ' (' + cl.role + ') <' + cl.email + '>';
  } else {
    reporter = team[Math.floor(Math.random() * team.length)];
  }

  let prompt = '';

  if (s.cat === 'known') {
    // For KNOWN, Gemini must yield the EXACT title and context to hit the >85% threshold
    prompt = 'You are simulating an incident generator. Return a JSON object with exactly these fields:\n'
      + '1. "title": "' + s.base + '"\n'
      + '2. "description": "' + s.ctx + '"\n'
      + '3. "reporter": "' + reporter + '"\n'
      + '4. "source": "webhook"\n\n'
      + 'Return ONLY valid JSON. No markdown wrapper.';
  } else {
    // For Mid and Unknown, Gemini generates unique specific details
    prompt = 'You are an advanced AI software team simulator. Generate a HIGHLY realistic bug report.\n\n'
      + '### SCENARIO:\n'
      + '- Category: ' + s.cat + '\n'
      + '- Base Concept: ' + s.base + '\n'
      + '- Context: ' + s.ctx + '\n\n'
      + '### UNIQUE PARAMETERS:\n'
      + '- Session ID: ' + randId + '\n'
      + '- Reference Code: ' + orderNum + '\n'
      + '- User ID: ' + uuidSample + '\n'
      + '- Port: ' + port + '\n'
      + '- Timestamp: ' + timestamp + '\n\n'
      + '### TEAM INVOLVED:\n' + participants + '\n\n'
      + '### INSTRUCTIONS:\n'
      + 'Generate a JSON object with exactly these 4 fields:\n'
      + '1. "title": A professional, highly specific, and mathematically unique Jira-style bug title with [Category] prefix. Example: "[Facilities] ' + s.base + ' for reference ' + randId + '"\n'
      + '2. "description": A RICH description (500-1500 chars) that includes:\n'
      + '   - A simulated discussion conversation referencing the parameters ' + randId + ', ' + orderNum + ', and ' + uuidSample + '.\n'
      + '   - Specific steps to reproduce.\n'
      + '   - Error messages or stack trace logs containing unique transaction ID ' + randId + '.\n'
      + '3. "reporter": "' + reporter + '"\n'
      + '4. "source": "webhook"\n\n'
      + 'Return ONLY valid JSON. No markdown wrapping.';
  }

  const geminiBody = {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: {
      responseMimeType: 'application/json',
      responseSchema: {
        type: 'OBJECT',
        properties: {
          title: { type: 'STRING' },
          description: { type: 'STRING' },
          reporter: { type: 'STRING' },
          source: { type: 'STRING' }
        },
        required: ['title', 'description', 'reporter', 'source']
      },
      temperature: 0.95
    }
  };

  output.push({ json: { geminiBody, category: s.cat, incidentNum: i + 1 } });
}

return output;

const resp = $input.first().json;
let text = '';
if (resp.candidates && resp.candidates[0] && resp.candidates[0].content) {
  text = resp.candidates[0].content.parts[0].text;
}
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```json?\n?/, '').replace(/\n?```$/, '');
}
text = text.trim();
const bug = JSON.parse(text);
return [{
  json: {
    title: bug.title || 'Untitled Incident',
    description: bug.description || '',
    source: bug.source || 'webhook',
    reporter: bug.reporter || 'simulator@fixflow.co'
  }
}];
